function humanLabel(value){if(value==null)return '';let key=String(value);if(HUMAN_LABELS[key])return HUMAN_LABELS[key];return key.replace(/[._-]+/g,' ').replace(/([a-z0-9])([A-Z])/g,'$1 $2').replace(/\b\w/g,c=>c.toUpperCase())}
